//! Read-only resolution of the launcher's generated subset of UAPKG config.
//!
//! The embedded schema and its defaults are generated by `@uapkg/config`.
//! User configuration failures are diagnostics, never resolver errors.

use jsonschema::Validator;
use serde::Serialize;
use serde_json::{Map, Value};
use std::{
    collections::{BTreeMap, BTreeSet},
    fmt, fs,
    path::{Component, Path, PathBuf},
};

pub const SCHEMA: &str = include_str!("../generated/slim-config.schema.json");

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Scope {
    Effective,
    Global,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum Source {
    Default,
    Global,
    Intermediary,
    Local,
}

impl Source {
    pub fn as_str(self) -> &'static str {
        match self {
            Self::Default => "default",
            Self::Global => "global",
            Self::Intermediary => "intermediary",
            Self::Local => "local",
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq, Serialize)]
pub struct Origin {
    pub source: Source,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub file: Option<PathBuf>,
}

impl fmt::Display for Origin {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        if let Some(file) = &self.file {
            write!(
                formatter,
                "{} config {}",
                self.source.as_str(),
                file.display()
            )
        } else {
            formatter.write_str("the built-in default")
        }
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize)]
#[serde(rename_all = "lowercase")]
pub enum TraceStatus {
    Accepted,
    Ignored,
}

#[derive(Clone, Debug, PartialEq, Serialize)]
pub struct TraceEntry {
    #[serde(flatten)]
    pub origin: Origin,
    pub value: Value,
    pub status: TraceStatus,
    #[serde(skip_serializing_if = "Option::is_none")]
    pub reason: Option<String>,
}

#[derive(Clone, Debug, PartialEq, Serialize)]
pub struct RetainedValue {
    pub path: String,
    pub value: Value,
    pub origin: Origin,
}

#[derive(Clone, Debug, PartialEq, Serialize)]
pub struct Diagnostic {
    pub source: Source,
    pub file: PathBuf,
    pub path: String,
    pub expected: String,
    pub received: String,
    pub reason: Option<String>,
    pub retained: Vec<RetainedValue>,
}

impl fmt::Display for Diagnostic {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(
            formatter,
            "Ignored {} in {} config {}: expected {}, received {}.",
            self.path,
            self.source.as_str(),
            self.file.display(),
            self.expected,
            self.received
        )?;
        if let Some(reason) = &self.reason {
            write!(formatter, " {reason}.")?;
        }
        for retained in &self.retained {
            write!(
                formatter,
                " Using {} for {} from {}.",
                preview(&retained.value),
                retained.path,
                retained.origin
            )?;
        }
        Ok(())
    }
}

#[derive(Clone, Debug, PartialEq)]
pub struct Resolution {
    pub value: Value,
    pub origins: BTreeMap<String, Origin>,
    pub trace: BTreeMap<String, Vec<TraceEntry>>,
    pub diagnostics: Vec<Diagnostic>,
}

impl Resolution {
    pub fn get(&self, path: &str) -> Option<&Value> {
        value_at(&self.value, path)
    }

    pub fn origin(&self, path: &str) -> Option<&Origin> {
        self.origins.get(path)
    }
}

struct Node {
    path: String,
    validator: Validator,
    expected: String,
    properties: BTreeMap<String, Node>,
    object: bool,
}

impl Node {
    fn compile(schema: &Value, path: String) -> Result<Self, String> {
        let properties = schema.get("properties").and_then(Value::as_object);
        let object = properties.is_some();
        let expected = schema
            .get("description")
            .and_then(Value::as_str)
            .map(str::to_owned)
            .unwrap_or_else(|| match schema.get("type").and_then(Value::as_str) {
                Some("object") => "an object".to_owned(),
                Some("boolean") => "a boolean (true or false)".to_owned(),
                Some("string") => "a string".to_owned(),
                Some(kind) => format!("a {kind}"),
                None => "a value matching the config schema".to_owned(),
            });
        // Containers are validated independently of their leaves so an invalid
        // sibling never prevents acceptance of a valid consumed property.
        let validation_schema = if object {
            serde_json::json!({"type": "object"})
        } else {
            schema.clone()
        };
        let validator = jsonschema::draft202012::options()
            .build(&validation_schema)
            .map_err(|error| format!("Invalid slim-config schema at {path}: {error}"))?;
        let mut children = BTreeMap::new();
        if let Some(properties) = properties {
            for (key, schema) in properties {
                let child_path = if path == "$" {
                    key.clone()
                } else {
                    format!("{path}.{key}")
                };
                children.insert(key.clone(), Self::compile(schema, child_path)?);
            }
        }
        Ok(Self {
            path,
            validator,
            expected,
            properties: children,
            object,
        })
    }

    fn apply(&self, candidate: &Value, origin: &Origin, result: &mut Resolution) {
        if !self.validator.is_valid(candidate) {
            let received = if self.object {
                describe_type(candidate).to_owned()
            } else {
                describe(candidate)
            };
            let reason = format!(
                "Expected {}; received {received}; value ignored",
                self.expected
            );
            self.trace_ignored(candidate, origin, &reason, &self.path, result);
            result.diagnostics.push(Diagnostic {
                source: origin.source,
                file: origin.file.clone().expect("file layers always have paths"),
                path: self.path.clone(),
                expected: self.expected.clone(),
                received,
                reason: None,
                retained: Vec::new(),
            });
            return;
        }
        if self.object {
            let object = candidate.as_object().expect("validated config container");
            for (key, child) in &self.properties {
                if let Some(candidate) = object.get(key) {
                    child.apply(candidate, origin, result);
                }
            }
        } else {
            set_value(&mut result.value, &self.path, candidate.clone());
            result.origins.insert(self.path.clone(), origin.clone());
            result
                .trace
                .entry(self.path.clone())
                .or_default()
                .push(TraceEntry {
                    origin: origin.clone(),
                    value: candidate.clone(),
                    status: TraceStatus::Accepted,
                    reason: None,
                });
        }
    }

    fn trace_ignored(
        &self,
        candidate: &Value,
        origin: &Origin,
        reason: &str,
        ancestor: &str,
        result: &mut Resolution,
    ) {
        let inherited = self.path != ancestor;
        result
            .trace
            .entry(self.path.clone())
            .or_default()
            .push(TraceEntry {
                origin: origin.clone(),
                // An invalid ancestor is not this leaf's value. Its explanation is
                // useful for tracing, but unrelated ancestor contents are not.
                value: if inherited {
                    Value::Null
                } else {
                    candidate.clone()
                },
                status: TraceStatus::Ignored,
                reason: Some(if inherited {
                    format!("Ancestor {ancestor} was ignored: {reason}")
                } else {
                    reason.to_owned()
                }),
            });
        for child in self.properties.values() {
            child.trace_ignored(candidate, origin, reason, ancestor, result);
        }
    }

    fn defaults(&self, values: &Value, result: &mut Resolution) {
        if self.object {
            for child in self.properties.values() {
                child.defaults(values, result);
            }
        } else if let Some(value) = value_at(values, &self.path) {
            let origin = Origin {
                source: Source::Default,
                file: None,
            };
            result.origins.insert(self.path.clone(), origin.clone());
            result
                .trace
                .entry(self.path.clone())
                .or_default()
                .push(TraceEntry {
                    origin,
                    value: value.clone(),
                    status: TraceStatus::Accepted,
                    reason: None,
                });
        }
    }
}

pub struct Resolver {
    root: Node,
    defaults: Value,
}

impl Resolver {
    /// Invalid embedded schemas are build defects, unlike invalid user config.
    pub fn new() -> Result<Self, String> {
        let schema: Value = serde_json::from_str(SCHEMA)
            .map_err(|error| format!("Invalid embedded slim-config schema JSON: {error}"))?;
        let validator = jsonschema::draft202012::options()
            .build(&schema)
            .map_err(|error| format!("Invalid embedded slim-config schema: {error}"))?;
        let defaults = schema
            .get("default")
            .cloned()
            .ok_or("The embedded slim-config schema has no defaults")?;
        validator
            .validate(&defaults)
            .map_err(|error| format!("Invalid embedded slim-config defaults: {error}"))?;
        let root = Node::compile(&schema, "$".to_owned())?;
        Ok(Self { root, defaults })
    }

    pub fn resolve(&self, profile_root: &Path, cwd: &Path, scope: Scope) -> Resolution {
        let profile_root = absolute_normalized(profile_root);
        let cwd = absolute_normalized(cwd);
        let mut result = Resolution {
            value: self.defaults.clone(),
            origins: BTreeMap::new(),
            trace: BTreeMap::new(),
            diagnostics: Vec::new(),
        };
        self.root.defaults(&self.defaults, &mut result);
        self.read(
            &profile_root.join("config.json"),
            Source::Global,
            &mut result,
        );
        if scope == Scope::Effective {
            let boundary = cwd
                .ancestors()
                .find(|directory| directory.join("uapkg.json").exists())
                .unwrap_or(&cwd);
            let mut ancestors: Vec<_> = cwd
                .ancestors()
                .take_while(|directory| *directory != boundary)
                .collect();
            if boundary != cwd {
                ancestors.push(boundary);
            }
            ancestors.reverse();
            for directory in ancestors {
                if directory != cwd {
                    let file = directory.join(".uapkg/config.json");
                    if file.exists() {
                        self.read(&file, Source::Intermediary, &mut result);
                    }
                }
            }
            self.read(&cwd.join(".uapkg/config.json"), Source::Local, &mut result);
        }
        // The active profile file can also be the cwd local file (for example
        // when running from the user's home). Keep both trace roles while
        // reporting each physical problem only once.
        let mut reported = BTreeSet::new();
        result.diagnostics.retain(|diagnostic| {
            reported.insert((
                diagnostic.file.clone(),
                diagnostic.path.clone(),
                diagnostic.expected.clone(),
                diagnostic.received.clone(),
                diagnostic.reason.clone(),
            ))
        });
        for diagnostic in &mut result.diagnostics {
            for (path, origin) in &result.origins {
                if diagnostic.path == "$"
                    || path == &diagnostic.path
                    || path.starts_with(&format!("{}.", diagnostic.path))
                {
                    diagnostic.retained.push(RetainedValue {
                        path: path.clone(),
                        value: value_at(&result.value, path)
                            .expect("resolved origin has a value")
                            .clone(),
                        origin: origin.clone(),
                    });
                }
            }
        }
        result
    }

    fn read(&self, file: &Path, source: Source, result: &mut Resolution) {
        let origin = Origin {
            source,
            file: Some(file.to_owned()),
        };
        let bytes = match fs::read(file) {
            Ok(bytes) => bytes,
            Err(error) if error.kind() == std::io::ErrorKind::NotFound => return,
            Err(error) => {
                let reason = format!("Could not read the file ({}); file ignored", error.kind());
                self.root
                    .trace_ignored(&Value::Null, &origin, &reason, "$", result);
                result.diagnostics.push(Diagnostic {
                    source,
                    file: file.to_owned(),
                    path: "$".to_owned(),
                    expected: "a readable JSON object".to_owned(),
                    received: "an unreadable file".to_owned(),
                    reason: Some(reason),
                    retained: Vec::new(),
                });
                return;
            }
        };
        // Node reads UTF-8 with replacement and String.trim also removes a BOM.
        let text = String::from_utf8_lossy(&bytes);
        let text = text.trim_matches(ecmascript_whitespace);
        if text.is_empty() {
            return;
        }
        let value = match serde_json::from_str::<Value>(text) {
            Ok(value) => value,
            Err(error) => {
                let reason = format!(
                    "JSON could not be parsed at line {}, column {}; file ignored",
                    error.line(),
                    error.column()
                );
                self.root
                    .trace_ignored(&Value::Null, &origin, &reason, "$", result);
                result.diagnostics.push(Diagnostic {
                    source,
                    file: file.to_owned(),
                    path: "$".to_owned(),
                    expected: "a valid JSON object".to_owned(),
                    received: "malformed JSON".to_owned(),
                    reason: Some(reason),
                    retained: Vec::new(),
                });
                return;
            }
        };
        self.root.apply(&value, &origin, result);
    }
}

fn value_at<'a>(value: &'a Value, path: &str) -> Option<&'a Value> {
    if path == "$" {
        return Some(value);
    }
    path.split('.')
        .try_fold(value, |value, segment| value.get(segment))
}

fn set_value(value: &mut Value, path: &str, candidate: Value) {
    let mut segments = path.split('.').peekable();
    let mut current = value;
    while let Some(segment) = segments.next() {
        if segments.peek().is_none() {
            current
                .as_object_mut()
                .expect("schema config object")
                .insert(segment.to_owned(), candidate);
            return;
        }
        current = current
            .as_object_mut()
            .expect("schema config object")
            .entry(segment)
            .or_insert_with(|| Value::Object(Map::new()));
    }
}

fn describe(value: &Value) -> String {
    match value {
        Value::Object(_) => "an object".to_owned(),
        Value::Array(_) => "an array".to_owned(),
        Value::Null => "null".to_owned(),
        Value::String(_) => format!("string {}", preview(value)),
        Value::Bool(_) => format!("boolean {value}"),
        Value::Number(_) => format!("number {value}"),
    }
}

fn describe_type(value: &Value) -> &'static str {
    match value {
        Value::Object(_) => "an object",
        Value::Array(_) => "an array",
        Value::Null => "null",
        Value::String(_) => "a string",
        Value::Bool(_) => "a boolean",
        Value::Number(_) => "a number",
    }
}

fn preview(value: &Value) -> String {
    let text: String = value
        .to_string()
        .chars()
        .flat_map(|character| {
            if character.is_control() {
                format!("\\u{{{:04x}}}", u32::from(character))
                    .chars()
                    .collect::<Vec<_>>()
            } else {
                vec![character]
            }
        })
        .collect();
    let mut characters = text.chars();
    let mut bounded: String = characters.by_ref().take(100).collect();
    if characters.next().is_some() {
        bounded.push('…');
    }
    bounded
}

fn ecmascript_whitespace(character: char) -> bool {
    matches!(character, '\u{0009}'..='\u{000d}' | '\u{0020}' | '\u{00a0}' | '\u{1680}' | '\u{2000}'..='\u{200a}' | '\u{2028}' | '\u{2029}' | '\u{202f}' | '\u{205f}' | '\u{3000}' | '\u{feff}')
}

fn absolute_normalized(path: &Path) -> PathBuf {
    let absolute = std::path::absolute(path).unwrap_or_else(|_| path.to_owned());
    let mut normalized = PathBuf::new();
    for component in absolute.components() {
        match component {
            Component::ParentDir => {
                normalized.pop();
            }
            Component::CurDir => {}
            other => normalized.push(other),
        }
    }
    normalized
}

